BEGIN;

CREATE OR REPLACE FUNCTION ingestion.source_graph_jobkorea_collision_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text) LANGUAGE plpgsql STABLE AS $$
BEGIN
 IF to_regclass('cs.posting_input') IS NULL THEN RETURN; END IF;
 RETURN QUERY EXECUTE $query$
  SELECT r.run_id,'JOBKOREA_CS_IDENTITY_COLLISION'::text,r.locator
  FROM ingestion.record r JOIN ingestion.run u USING(run_id)
  JOIN cs.posting_input i ON i.source_id='jobkorea' AND i.snapshot_run_id=r.run_id
   AND i.source_posting_id=r.source_record_id
  WHERE u.source_id='jobkorea' AND r.run_id=$1
 $query$ USING jobs;
END $$;

-- JobKorea is optional. A graph-only install keeps the original fail-closed
-- local hook; install this additive file again after its adapter is added.
DO $optional_jobkorea$ BEGIN
 IF to_regclass('ingestion.jobkorea_import') IS NOT NULL
 AND to_regprocedure('ingestion.jobkorea_ndjson_row_manifest(text)') IS NOT NULL THEN
 EXECUTE $definition$
CREATE OR REPLACE FUNCTION ingestion.source_graph_jobkorea_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text)
LANGUAGE sql STABLE SET jit=off AS $$
WITH runs AS MATERIALIZED (SELECT * FROM ingestion.run WHERE run_id=jobs),
imports AS MATERIALIZED (SELECT * FROM ingestion.jobkorea_import WHERE run_id=jobs),
issues AS MATERIALIZED (SELECT * FROM ingestion.jobkorea_issue WHERE run_id=jobs),
documents AS MATERIALIZED (SELECT * FROM ingestion.document WHERE run_id=jobs),
partitions AS MATERIALIZED (SELECT * FROM ingestion.partition WHERE run_id=jobs),
records AS MATERIALIZED (SELECT * FROM ingestion.record WHERE run_id=jobs),
rejected AS MATERIALIZED (SELECT * FROM ingestion.rejected_row WHERE run_id=jobs),
manifests AS MATERIALIZED (SELECT i.run_id, CASE WHEN i.file_format='NDJSON'
 THEN ingestion.jobkorea_ndjson_row_manifest(i.run_id)
 WHEN i.loaded THEN ingestion.jobkorea_row_manifest(i.run_id) END AS digest FROM imports i)
SELECT i.run_id,i.code AS issue,i.locator||CASE WHEN i.field<>'' THEN ':'||i.field ELSE '' END AS location
FROM issues i WHERE i.severity='ERROR'
UNION ALL
SELECT u.run_id,'JOBKOREA_IMPORT_PROVENANCE_MISSING','' FROM runs u
WHERE u.source_id='jobkorea' AND NOT EXISTS(SELECT 1 FROM imports i WHERE i.run_id=u.run_id)
UNION ALL
SELECT i.run_id,'JOBKOREA_IMPORT_METADATA_CONFLICT','' FROM imports i
JOIN runs u USING(run_id)
WHERE u.source_id<>'jobkorea' OR u.mode<>'REPLAY' OR u.parser_version<>i.parser_version OR u.policy_revision<>i.policy_revision
 OR i.policy_revision<>'2026-10-07.1'
 OR (i.file_format='JSON_ARRAY' AND (i.parser_version<>'hop-jobkorea-v1'
  OR i.raw_path<>'jobkorea/'||i.file_sha256||'/source.json'
  OR i.run_id<>'jobkorea-'||encode(sha256(convert_to('hop-jobkorea-v1:2026-10-07.1:'||i.file_sha256,'UTF8')),'hex')))
 OR (i.file_format='NDJSON' AND (i.parser_version<>'hop-jobkorea-ndjson-v1'
  OR i.raw_path<>'jobkorea/'||i.file_sha256||'/source.ndjson'
  OR i.run_id<>'jobkorea-ndjson-'||encode(sha256(convert_to('hop-jobkorea-ndjson-v1:2026-10-07.1:'||i.file_sha256,'UTF8')),'hex')))
 OR i.scope<>'FILE_ONLY' OR i.provider_complete
UNION ALL
SELECT i.run_id,'JOBKOREA_FILE_NOT_PROCESSED','' FROM imports i
WHERE NOT i.loaded OR i.processed_at IS NULL OR i.payload_sha256 IS DISTINCT FROM i.file_sha256 OR i.error_code IS NOT NULL
UNION ALL
SELECT i.run_id,'JOBKOREA_ROW_MANIFEST_CONFLICT','' FROM imports i
WHERE i.loaded AND i.row_manifest_sha256 IS DISTINCT FROM (SELECT m.digest FROM manifests m WHERE m.run_id=i.run_id)
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCAL_DOCUMENT_CONFLICT',i.document_id FROM imports i
LEFT JOIN documents d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE d.document_id IS NULL OR d.transport<>'LOCAL_FILE' OR d.http_status IS NOT NULL OR d.provider_result IS NOT NULL
 OR d.raw_sha256<>i.file_sha256 OR d.byte_length<>i.byte_length OR d.raw_path<>i.raw_path OR d.encoding<>'UTF-8'
 OR d.retrieved_at<>i.received_at OR d.partition_id<>'local-file' OR d.page_no<>1 OR d.confirmation_no<>0 OR d.attempt_no<>1
 OR NOT d.selected OR d.verified_at IS NULL
 OR d.item_count IS NULL OR d.item_count=0 OR d.declared_total IS DISTINCT FROM d.item_count
 OR d.effective_page<>1 OR d.effective_page_size IS DISTINCT FROM d.item_count
 OR (SELECT count(*) FROM documents x WHERE x.run_id=i.run_id)<>1
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCAL_PARTITION_CONFLICT','local-file' FROM imports i
LEFT JOIN partitions p ON p.run_id=i.run_id AND p.partition_id='local-file'
LEFT JOIN documents d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE p.partition_id IS NULL OR p.kind<>'FILE' OR p.expected_total IS DISTINCT FROM d.item_count
 OR p.page_size IS DISTINCT FROM d.item_count
 OR p.request_context IS DISTINCT FROM '{"transport":"LOCAL_FILE","scope":"FILE_ONLY","provider_complete":false,"absence_is_closure":false}'::jsonb
 OR (SELECT count(*) FROM partitions x WHERE x.run_id=i.run_id)<>1
UNION ALL
SELECT r.run_id,'JOBKOREA_RECORD_NORMALIZATION_CONFLICT',r.locator
FROM records r JOIN runs u USING(run_id)
JOIN imports i USING(run_id)
CROSS JOIN LATERAL ingestion.normalize_jobkorea_row(r.source_payload,r.locator) n
WHERE u.source_id='jobkorea' AND (r.normalized IS DISTINCT FROM n.normalized OR r.field_lineage IS DISTINCT FROM n.field_lineage
 OR r.quality_flags IS DISTINCT FROM n.quality_flags OR jsonb_array_length(n.errors)>0
 OR r.source_record_id IS DISTINCT FROM r.normalized->>'posting_id'
 OR (i.file_format='JSON_ARRAY' AND r.locator !~ '^/(0|[1-9][0-9]*)$')
 OR (i.file_format='NDJSON' AND r.locator !~ '^line:[1-9][0-9]*$')
 OR r.document_id<>'local-json')
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCATOR_ACCOUNTING_CONFLICT','' FROM imports i
JOIN documents d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE i.file_format='JSON_ARRAY' AND d.item_count IS NOT NULL AND (
 (SELECT count(DISTINCT locator) FROM (
  SELECT locator FROM records r WHERE r.run_id=i.run_id
  UNION ALL SELECT locator FROM rejected r WHERE r.run_id=i.run_id) x)<>d.item_count
 OR EXISTS(SELECT 1 FROM (
  SELECT locator FROM records r WHERE r.run_id=i.run_id
  UNION ALL SELECT locator FROM rejected r WHERE r.run_id=i.run_id) x
  WHERE x.locator !~ '^/(0|[1-9][0-9]*)$' OR length(x.locator)>12
   OR CASE WHEN x.locator ~ '^/(0|[1-9][0-9]*)$' AND length(x.locator)<=12
     THEN substring(x.locator FROM 2)::bigint>=d.item_count ELSE true END))
UNION ALL
SELECT u.run_id,'JOBKOREA_UNEXPECTED_HTTP_REQUEST','' FROM runs u
WHERE u.source_id='jobkorea' AND EXISTS(SELECT 1 FROM ingestion.request_attempt a WHERE a.run_id=u.run_id)
UNION ALL
SELECT u.run_id,'JOBKOREA_UNEXPECTED_DEPENDENCY','' FROM runs u
WHERE u.source_id='jobkorea' AND EXISTS(SELECT 1 FROM ingestion.dependency a WHERE a.run_id=u.run_id)
UNION ALL
SELECT * FROM ingestion.source_graph_jobkorea_collision_issue(jobs)
UNION ALL SELECT i.run_id,'JOBKOREA_NDJSON_CHECKPOINT_INCOMPLETE','' FROM imports i
 WHERE i.file_format='NDJSON' AND (i.next_byte_offset<>i.byte_length OR i.next_line_number<=1 OR i.batch_count<=0)
 UNION ALL
 SELECT i.run_id,'JOBKOREA_NDJSON_LINE_ACCOUNTING_CONFLICT','' FROM imports i
 WHERE i.file_format='NDJSON' AND (
  (SELECT count(*) FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=i.run_id)<>i.next_line_number-1
  OR (SELECT count(*) FROM ingestion.record r WHERE r.run_id=i.run_id)
   +(SELECT count(*) FROM ingestion.rejected_row r WHERE r.run_id=i.run_id)<>i.next_line_number-1
  OR EXISTS(SELECT 1 FROM ingestion.record r WHERE r.run_id=i.run_id AND NOT EXISTS(
   SELECT 1 FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=r.run_id
    AND l.line_number=CASE WHEN r.locator ~ '^line:[1-9][0-9]{0,9}$' THEN substring(r.locator FROM 6)::bigint END
    AND l.source_record_id=r.source_record_id))
  OR EXISTS(SELECT 1 FROM ingestion.rejected_row r WHERE r.run_id=i.run_id AND NOT EXISTS(
   SELECT 1 FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=r.run_id
    AND l.line_number=CASE WHEN r.locator ~ '^line:[1-9][0-9]{0,9}$' THEN substring(r.locator FROM 6)::bigint END)))
 UNION ALL
 SELECT i.run_id,'JOBKOREA_NDJSON_CHAIN_CONFLICT','' FROM imports i
 WHERE i.file_format='NDJSON' AND (SELECT m.digest FROM manifests m WHERE m.run_id=i.run_id) IS NULL
$$;
$definition$;
 END IF;
END $optional_jobkorea$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_local_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text)
LANGUAGE sql STABLE AS $$ SELECT v.* FROM ingestion.local_file_validation_issue() v
 WHERE v.run_id=jobs $$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_scoped_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text)
LANGUAGE sql STABLE SET jit=off AS $$
WITH
runs AS MATERIALIZED (SELECT * FROM ingestion.run WHERE run_id=jobs),
partitions AS MATERIALIZED (SELECT * FROM ingestion.partition WHERE run_id=jobs),
documents AS MATERIALIZED (SELECT * FROM ingestion.document WHERE run_id=jobs),
records AS MATERIALIZED (SELECT * FROM ingestion.record WHERE run_id=jobs),
dependencies AS MATERIALIZED (SELECT * FROM ingestion.dependency WHERE run_id=jobs),
rejected AS MATERIALIZED (SELECT * FROM ingestion.rejected_row WHERE run_id=jobs),
selected AS MATERIALIZED (
    SELECT d.* FROM documents d WHERE d.selected
), facts AS MATERIALIZED (
    SELECT r.run_id,r.document_id,r.locator,r.source_record_id,r.normalized,d.partition_id
    FROM records r JOIN selected d USING (run_id, document_id)
), document_counts AS (SELECT run_id,partition_id,count(document_id) AS documents,
 min(page_no) AS first_page,max(page_no) AS last_page FROM selected
 GROUP BY run_id,partition_id),
partition_counts AS (SELECT p.*,coalesce(c.documents,0) AS documents,
 c.first_page,c.last_page FROM partitions p
 LEFT JOIN document_counts c USING(run_id,partition_id)), pairs AS (
    SELECT f.run_id, f.normalized->>'posting_id' AS posting_id,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'list') AS lists,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'detail') AS details
    FROM facts f JOIN runs u USING (run_id)
    WHERE u.source_id = 'job_alio'
    GROUP BY f.run_id, f.normalized->>'posting_id'
), nara_pairs AS (
    SELECT f.run_id,f.normalized->>'posting_id' AS posting_id,
      count(*) FILTER(WHERE f.normalized->>'representation'='list') AS lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='list' AND coalesce((f.normalized->>'ongoing')::boolean,false)) AS active_lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='detail') AS details,
      count(*) FILTER(WHERE f.normalized->>'representation'='positions') AS positions,
      count(*) FILTER(WHERE f.normalized->>'representation'='files') AS files
    FROM facts f JOIN runs u USING(run_id)
    WHERE u.source_id='nara_job'
    GROUP BY f.run_id,f.normalized->>'posting_id'
)
SELECT u.run_id, 'SMOKE_NOT_FULL'::text AS issue, ''::text AS location
FROM runs u WHERE u.mode = 'SMOKE'
UNION ALL
SELECT u.run_id, 'NO_PARTITIONS', '' FROM runs u
WHERE NOT EXISTS (SELECT 1 FROM partitions p WHERE p.run_id = u.run_id)
UNION ALL
SELECT d.run_id, 'DEPENDENCY_NOT_READY_OR_WRONG_SOURCE', d.input_source_id
FROM dependencies d JOIN ingestion.run u ON u.run_id = d.input_run_id
WHERE u.state <> 'READY' OR u.mode = 'SMOKE' OR u.source_id <> d.input_source_id
UNION ALL
SELECT u.run_id, 'MISSING_DEPENDENCY', u.source_id
FROM runs u
WHERE u.source_id IN ('ncs_qualification', 'qnet_schedule', 'job_alio')
  AND NOT EXISTS (
      SELECT 1 FROM dependencies d WHERE d.run_id = u.run_id
      AND d.input_source_id = CASE u.source_id
          WHEN 'ncs_qualification' THEN 'ncs_competency'
          WHEN 'qnet_schedule' THEN 'ncs_qualification'
          WHEN 'job_alio' THEN 'alio_organization' END)
UNION ALL
SELECT run_id, 'PARTITION_INCOMPLETE', partition_id FROM partition_counts
WHERE expected_total IS NULL
   OR (kind = 'PAGED' AND (documents <> CASE WHEN expected_total = 0 THEN 2
                    ELSE ceil(expected_total::numeric / page_size)::integer END
       OR first_page <> 1
       OR last_page <> greatest(1, ceil(expected_total::numeric / page_size)::integer)))
   OR (kind <> 'PAGED' AND (documents <> 1 OR first_page <> 1 OR last_page <> 1))
UNION ALL
SELECT d.run_id, 'DOCUMENT_METADATA_OR_FILE_NOT_VERIFIED', d.document_id
FROM selected d
JOIN partitions p USING (run_id, partition_id)
JOIN runs u USING (run_id)
WHERE (coalesce(to_jsonb(d)->>'transport','HTTP')='HTTP' AND d.http_status IS DISTINCT FROM 200)
   OR (coalesce(to_jsonb(d)->>'transport','HTTP')='LOCAL_FILE' AND
       (u.source_id<>'jobkorea' OR d.http_status IS NOT NULL OR d.provider_result IS NOT NULL))
   OR d.byte_length = 0 OR d.verified_at IS NULL
   OR d.item_count IS NULL OR d.effective_page IS DISTINCT FROM d.page_no
   OR (p.kind = 'PAGED' AND (
          d.declared_total IS DISTINCT FROM p.expected_total
       OR d.effective_page_size IS DISTINCT FROM p.page_size
       OR d.item_count IS DISTINCT FROM
            greatest(0, least(p.page_size, p.expected_total - (d.page_no - 1) * p.page_size))
       OR (p.expected_total > 0 AND d.confirmation_no <> 0)
       OR (p.expected_total = 0 AND d.page_no <> 1)))
   OR (p.kind = 'DETAIL' AND (d.item_count <> 1 OR d.confirmation_no <> 0))
   OR (p.kind = 'FILE' AND (d.item_count IS DISTINCT FROM p.expected_total
                          OR d.item_count = 0 OR d.confirmation_no <> 0))
   OR (u.source_id IN ('alio_organization', 'job_alio')
       AND d.provider_result IS DISTINCT FROM '200')
   OR (u.source_id IN ('ncs_qualification', 'qnet_schedule')
       AND (d.provider_result IS NULL OR d.provider_result NOT IN ('00', '0', 'SUCCESS')))
UNION ALL
SELECT d.run_id, 'ROW_COUNT_MISMATCH', d.document_id FROM selected d
WHERE d.item_count IS DISTINCT FROM (
    (SELECT count(*) FROM records r
     WHERE r.run_id = d.run_id AND r.document_id = d.document_id)
  + (SELECT count(*) FROM rejected e
     WHERE e.run_id = d.run_id AND e.document_id = d.document_id))
UNION ALL
SELECT e.run_id, 'REJECTED_ROW', e.document_id || ':' || e.locator
FROM rejected e JOIN selected d USING (run_id, document_id)
UNION ALL
SELECT run_id, 'DUPLICATE_SOURCE_ID', source_record_id FROM facts
GROUP BY run_id, source_record_id HAVING count(*) <> 1
UNION ALL
SELECT f.run_id, 'WRONG_RECORD_KIND', f.document_id || ':' || f.locator
FROM facts f JOIN runs u USING (run_id)
WHERE f.normalized->>'kind' IS DISTINCT FROM CASE u.source_id
    WHEN 'alio_organization' THEN 'Organization' WHEN 'job_alio' THEN 'JobPosting'
    WHEN 'nara_job' THEN 'JobPosting' WHEN 'jobkorea' THEN 'JobPosting'
    WHEN 'ncs_career_path' THEN 'CareerPath' WHEN 'ncs_competency' THEN 'Competency'
    WHEN 'ncs_qualification' THEN 'QualificationMapping' WHEN 'qnet_schedule' THEN 'ExamSession' END
UNION ALL
SELECT f.run_id, 'PARTITION_IDENTITY_MISMATCH', f.document_id || ':' || f.locator
FROM facts f JOIN runs u USING (run_id)
WHERE (u.source_id = 'ncs_qualification'
       AND f.partition_id IS DISTINCT FROM 'ncs-' || (f.normalized->>'competency_code'))
   OR (u.source_id = 'qnet_schedule'
       AND f.partition_id IS DISTINCT FROM 'year-' || (f.normalized->>'year')
                                           || '-item-' || (f.normalized->>'qualification_code'))
   OR (u.source_id = 'job_alio' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' = 'detail'
           AND f.partition_id IS DISTINCT FROM 'detail-' || (f.normalized->>'posting_id'))))
   OR (u.source_id = 'nara_job' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' IN ('detail','positions','files')
           AND f.partition_id IS DISTINCT FROM (f.normalized->>'representation') || '-' || (f.normalized->>'posting_id'))))
UNION ALL
SELECT run_id, 'POSTING_PAIR_MISSING_OR_DUPLICATED', posting_id FROM pairs
WHERE lists <> 1 OR details <> 1
UNION ALL
SELECT run_id,'NARA_ACTIVE_RESOURCE_MISSING_OR_DUPLICATED',posting_id FROM nara_pairs
WHERE lists<>1 OR (active_lists=1 AND (details<>1 OR positions<>1 OR files<>1))
   OR (active_lists=0 AND (details<>0 OR positions<>0 OR files<>0))
UNION ALL
SELECT l.run_id,'NARA_POSTING_CONFLICT',l.normalized->>'posting_id'
FROM facts l JOIN runs u ON u.run_id=l.run_id AND u.source_id='nara_job'
JOIN facts d ON d.run_id=l.run_id AND d.normalized->>'posting_id'=l.normalized->>'posting_id'
 AND d.normalized->>'representation'='detail'
WHERE l.normalized->>'representation'='list'
 AND nullif(d.normalized->>'title','') IS NOT NULL
 AND l.normalized->>'title' IS DISTINCT FROM d.normalized->>'title'
UNION ALL
SELECT l.run_id, 'POSTING_PAIR_CONFLICT', l.normalized->>'posting_id'
FROM facts l JOIN runs u ON u.run_id=l.run_id AND u.source_id='job_alio'
JOIN facts d ON d.run_id = l.run_id
 AND d.normalized->>'posting_id' = l.normalized->>'posting_id'
 AND d.normalized->>'representation' = 'detail'
WHERE l.normalized->>'representation' = 'list'
  AND (l.normalized->'title' IS DISTINCT FROM d.normalized->'title'
    OR l.normalized->'organization_code' IS DISTINCT FROM d.normalized->'organization_code'
    OR l.normalized->'date_posted' IS DISTINCT FROM d.normalized->'date_posted'
    OR l.normalized->'closing_date' IS DISTINCT FROM d.normalized->'closing_date'
    OR (d.normalized->>'ongoing' IS NOT NULL
        AND l.normalized->'ongoing' IS DISTINCT FROM d.normalized->'ongoing'))
UNION ALL
SELECT run_id,issue,location FROM ingestion.source_graph_local_validation_issue(jobs)
$$;

DO $bind_rules$ DECLARE shared_hash text; jk_hash text; hook_hash text; nd_hash text; collision_hash text;
 wrapper text; local_wrapper text;
BEGIN
 CREATE TEMP VIEW source_query_expected_validation AS
WITH selected AS NOT MATERIALIZED (
    SELECT d.* FROM ingestion.document d WHERE d.selected
), facts AS NOT MATERIALIZED (
    SELECT r.run_id,r.document_id,r.locator,r.source_record_id,r.normalized,d.partition_id
    FROM ingestion.record r JOIN selected d USING (run_id, document_id)
), partition_counts AS (
    SELECT p.*, count(d.document_id) AS documents,
           min(d.page_no) AS first_page, max(d.page_no) AS last_page
    FROM ingestion.partition p
    LEFT JOIN selected d USING (run_id, partition_id)
    GROUP BY p.run_id, p.partition_id
), pairs AS (
    SELECT f.run_id, f.normalized->>'posting_id' AS posting_id,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'list') AS lists,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'detail') AS details
    FROM facts f JOIN ingestion.run u USING (run_id)
    WHERE u.source_id = 'job_alio'
    GROUP BY f.run_id, f.normalized->>'posting_id'
), nara_pairs AS (
    SELECT f.run_id,f.normalized->>'posting_id' AS posting_id,
      count(*) FILTER(WHERE f.normalized->>'representation'='list') AS lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='list' AND coalesce((f.normalized->>'ongoing')::boolean,false)) AS active_lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='detail') AS details,
      count(*) FILTER(WHERE f.normalized->>'representation'='positions') AS positions,
      count(*) FILTER(WHERE f.normalized->>'representation'='files') AS files
    FROM facts f JOIN ingestion.run u USING(run_id)
    WHERE u.source_id='nara_job'
    GROUP BY f.run_id,f.normalized->>'posting_id'
)
SELECT u.run_id, 'SMOKE_NOT_FULL'::text AS issue, ''::text AS location
FROM ingestion.run u WHERE u.mode = 'SMOKE'
UNION ALL
SELECT u.run_id, 'NO_PARTITIONS', '' FROM ingestion.run u
WHERE NOT EXISTS (SELECT 1 FROM ingestion.partition p WHERE p.run_id = u.run_id)
UNION ALL
SELECT d.run_id, 'DEPENDENCY_NOT_READY_OR_WRONG_SOURCE', d.input_source_id
FROM ingestion.dependency d JOIN ingestion.run u ON u.run_id = d.input_run_id
WHERE u.state <> 'READY' OR u.mode = 'SMOKE' OR u.source_id <> d.input_source_id
UNION ALL
SELECT u.run_id, 'MISSING_DEPENDENCY', u.source_id
FROM ingestion.run u
WHERE u.source_id IN ('ncs_qualification', 'qnet_schedule', 'job_alio')
  AND NOT EXISTS (
      SELECT 1 FROM ingestion.dependency d WHERE d.run_id = u.run_id
      AND d.input_source_id = CASE u.source_id
          WHEN 'ncs_qualification' THEN 'ncs_competency'
          WHEN 'qnet_schedule' THEN 'ncs_qualification'
          WHEN 'job_alio' THEN 'alio_organization' END)
UNION ALL
SELECT run_id, 'PARTITION_INCOMPLETE', partition_id FROM partition_counts
WHERE expected_total IS NULL
   OR (kind = 'PAGED' AND (documents <> CASE WHEN expected_total = 0 THEN 2
                    ELSE ceil(expected_total::numeric / page_size)::integer END
       OR first_page <> 1
       OR last_page <> greatest(1, ceil(expected_total::numeric / page_size)::integer)))
   OR (kind <> 'PAGED' AND (documents <> 1 OR first_page <> 1 OR last_page <> 1))
UNION ALL
SELECT d.run_id, 'DOCUMENT_METADATA_OR_FILE_NOT_VERIFIED', d.document_id
FROM selected d
JOIN ingestion.partition p USING (run_id, partition_id)
JOIN ingestion.run u USING (run_id)
WHERE (coalesce(to_jsonb(d)->>'transport','HTTP')='HTTP' AND d.http_status IS DISTINCT FROM 200)
   OR (coalesce(to_jsonb(d)->>'transport','HTTP')='LOCAL_FILE' AND
       (u.source_id<>'jobkorea' OR d.http_status IS NOT NULL OR d.provider_result IS NOT NULL))
   OR d.byte_length = 0 OR d.verified_at IS NULL
   OR d.item_count IS NULL OR d.effective_page IS DISTINCT FROM d.page_no
   OR (p.kind = 'PAGED' AND (
          d.declared_total IS DISTINCT FROM p.expected_total
       OR d.effective_page_size IS DISTINCT FROM p.page_size
       OR d.item_count IS DISTINCT FROM
            greatest(0, least(p.page_size, p.expected_total - (d.page_no - 1) * p.page_size))
       OR (p.expected_total > 0 AND d.confirmation_no <> 0)
       OR (p.expected_total = 0 AND d.page_no <> 1)))
   OR (p.kind = 'DETAIL' AND (d.item_count <> 1 OR d.confirmation_no <> 0))
   OR (p.kind = 'FILE' AND (d.item_count IS DISTINCT FROM p.expected_total
                          OR d.item_count = 0 OR d.confirmation_no <> 0))
   OR (u.source_id IN ('alio_organization', 'job_alio')
       AND d.provider_result IS DISTINCT FROM '200')
   OR (u.source_id IN ('ncs_qualification', 'qnet_schedule')
       AND (d.provider_result IS NULL OR d.provider_result NOT IN ('00', '0', 'SUCCESS')))
UNION ALL
SELECT d.run_id, 'ROW_COUNT_MISMATCH', d.document_id FROM selected d
WHERE d.item_count IS DISTINCT FROM (
    (SELECT count(*) FROM ingestion.record r
     WHERE r.run_id = d.run_id AND r.document_id = d.document_id)
  + (SELECT count(*) FROM ingestion.rejected_row e
     WHERE e.run_id = d.run_id AND e.document_id = d.document_id))
UNION ALL
SELECT e.run_id, 'REJECTED_ROW', e.document_id || ':' || e.locator
FROM ingestion.rejected_row e JOIN selected d USING (run_id, document_id)
UNION ALL
SELECT run_id, 'DUPLICATE_SOURCE_ID', source_record_id FROM facts
GROUP BY run_id, source_record_id HAVING count(*) <> 1
UNION ALL
SELECT f.run_id, 'WRONG_RECORD_KIND', f.document_id || ':' || f.locator
FROM facts f JOIN ingestion.run u USING (run_id)
WHERE f.normalized->>'kind' IS DISTINCT FROM CASE u.source_id
    WHEN 'alio_organization' THEN 'Organization' WHEN 'job_alio' THEN 'JobPosting'
    WHEN 'nara_job' THEN 'JobPosting' WHEN 'jobkorea' THEN 'JobPosting'
    WHEN 'ncs_career_path' THEN 'CareerPath' WHEN 'ncs_competency' THEN 'Competency'
    WHEN 'ncs_qualification' THEN 'QualificationMapping' WHEN 'qnet_schedule' THEN 'ExamSession' END
UNION ALL
SELECT f.run_id, 'PARTITION_IDENTITY_MISMATCH', f.document_id || ':' || f.locator
FROM facts f JOIN ingestion.run u USING (run_id)
WHERE (u.source_id = 'ncs_qualification'
       AND f.partition_id IS DISTINCT FROM 'ncs-' || (f.normalized->>'competency_code'))
   OR (u.source_id = 'qnet_schedule'
       AND f.partition_id IS DISTINCT FROM 'year-' || (f.normalized->>'year')
                                           || '-item-' || (f.normalized->>'qualification_code'))
   OR (u.source_id = 'job_alio' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' = 'detail'
           AND f.partition_id IS DISTINCT FROM 'detail-' || (f.normalized->>'posting_id'))))
   OR (u.source_id = 'nara_job' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' IN ('detail','positions','files')
           AND f.partition_id IS DISTINCT FROM (f.normalized->>'representation') || '-' || (f.normalized->>'posting_id'))))
UNION ALL
SELECT run_id, 'POSTING_PAIR_MISSING_OR_DUPLICATED', posting_id FROM pairs
WHERE lists <> 1 OR details <> 1
UNION ALL
SELECT run_id,'NARA_ACTIVE_RESOURCE_MISSING_OR_DUPLICATED',posting_id FROM nara_pairs
WHERE lists<>1 OR (active_lists=1 AND (details<>1 OR positions<>1 OR files<>1))
   OR (active_lists=0 AND (details<>0 OR positions<>0 OR files<>0))
UNION ALL
SELECT l.run_id,'NARA_POSTING_CONFLICT',l.normalized->>'posting_id'
FROM facts l JOIN ingestion.run u ON u.run_id=l.run_id AND u.source_id='nara_job'
JOIN facts d ON d.run_id=l.run_id AND d.normalized->>'posting_id'=l.normalized->>'posting_id'
 AND d.normalized->>'representation'='detail'
WHERE l.normalized->>'representation'='list'
 AND nullif(d.normalized->>'title','') IS NOT NULL
 AND l.normalized->>'title' IS DISTINCT FROM d.normalized->>'title'
UNION ALL
SELECT l.run_id, 'POSTING_PAIR_CONFLICT', l.normalized->>'posting_id'
FROM facts l JOIN ingestion.run u ON u.run_id=l.run_id AND u.source_id='job_alio'
JOIN facts d ON d.run_id = l.run_id
 AND d.normalized->>'posting_id' = l.normalized->>'posting_id'
 AND d.normalized->>'representation' = 'detail'
WHERE l.normalized->>'representation' = 'list'
  AND (l.normalized->'title' IS DISTINCT FROM d.normalized->'title'
    OR l.normalized->'organization_code' IS DISTINCT FROM d.normalized->'organization_code'
    OR l.normalized->'date_posted' IS DISTINCT FROM d.normalized->'date_posted'
    OR l.normalized->'closing_date' IS DISTINCT FROM d.normalized->'closing_date'
    OR (d.normalized->>'ongoing' IS NOT NULL
        AND l.normalized->'ongoing' IS DISTINCT FROM d.normalized->'ongoing'))
UNION ALL
SELECT run_id,issue,location FROM ingestion.local_file_validation_issue();

 IF pg_get_viewdef('source_query_expected_validation'::regclass,true)
  IS DISTINCT FROM pg_get_viewdef('ingestion.validation_issue'::regclass,true)
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_CANONICAL_VALIDATION_DRIFT'; END IF;
 DROP VIEW source_query_expected_validation;
 shared_hash:=md5(pg_get_viewdef('ingestion.validation_issue'::regclass,true));
 wrapper:=$definition$
CREATE OR REPLACE FUNCTION ingestion.source_graph_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text) LANGUAGE plpgsql STABLE SET jit=off AS $body$
BEGIN
 IF md5(pg_get_viewdef('ingestion.validation_issue'::regclass,true))=__SHARED_HASH__ THEN
  RETURN QUERY SELECT * FROM ingestion.source_graph_scoped_validation_issue(jobs);
 ELSE
  RETURN QUERY SELECT v.* FROM ingestion.validation_issue v WHERE v.run_id=jobs;
 END IF;
END $body$;
$definition$;
 EXECUTE replace(wrapper,'__SHARED_HASH__',quote_literal(shared_hash));
 IF to_regprocedure('ingestion.source_graph_jobkorea_validation_issue(text)') IS NOT NULL
  AND (SELECT p.prosrc FROM pg_proc p WHERE p.oid='ingestion.local_file_validation_issue()'::regprocedure)
    ='
 SELECT * FROM ingestion.jobkorea_validation_issue
'
 AND (SELECT p.prosrc FROM pg_proc p WHERE p.oid=to_regprocedure('ingestion.jobkorea_ndjson_validation_issue()'))='
 SELECT i.run_id,''JOBKOREA_NDJSON_CHECKPOINT_INCOMPLETE'','''' FROM ingestion.jobkorea_import i
 WHERE i.file_format=''NDJSON'' AND (i.next_byte_offset<>i.byte_length OR i.next_line_number<=1 OR i.batch_count<=0)
 UNION ALL
 SELECT i.run_id,''JOBKOREA_NDJSON_LINE_ACCOUNTING_CONFLICT'','''' FROM ingestion.jobkorea_import i
 WHERE i.file_format=''NDJSON'' AND (
  (SELECT count(*) FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=i.run_id)<>i.next_line_number-1
  OR (SELECT count(*) FROM ingestion.record r WHERE r.run_id=i.run_id)
   +(SELECT count(*) FROM ingestion.rejected_row r WHERE r.run_id=i.run_id)<>i.next_line_number-1
  OR EXISTS(SELECT 1 FROM ingestion.record r WHERE r.run_id=i.run_id AND NOT EXISTS(
   SELECT 1 FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=r.run_id
    AND l.line_number=CASE WHEN r.locator ~ ''^line:[1-9][0-9]{0,9}$'' THEN substring(r.locator FROM 6)::bigint END
    AND l.source_record_id=r.source_record_id))
  OR EXISTS(SELECT 1 FROM ingestion.rejected_row r WHERE r.run_id=i.run_id AND NOT EXISTS(
   SELECT 1 FROM ingestion.jobkorea_ndjson_line l WHERE l.run_id=r.run_id
    AND l.line_number=CASE WHEN r.locator ~ ''^line:[1-9][0-9]{0,9}$'' THEN substring(r.locator FROM 6)::bigint END)))
 UNION ALL
 SELECT i.run_id,''JOBKOREA_NDJSON_CHAIN_CONFLICT'','''' FROM ingestion.jobkorea_import i
 WHERE i.file_format=''NDJSON'' AND ingestion.jobkorea_ndjson_row_manifest(i.run_id) IS NULL
'
 AND (SELECT p.prosrc FROM pg_proc p WHERE p.oid=to_regprocedure('ingestion.jobkorea_cs_collision_issue()'))='
BEGIN
 IF to_regclass(''cs.posting_input'') IS NULL THEN RETURN; END IF;
 RETURN QUERY EXECUTE $query$
  SELECT r.run_id,''JOBKOREA_CS_IDENTITY_COLLISION''::text,r.locator
  FROM ingestion.record r JOIN ingestion.run u USING(run_id)
  JOIN cs.posting_input i ON i.source_id=''jobkorea'' AND i.snapshot_run_id=r.run_id
   AND i.source_posting_id=r.source_record_id
  WHERE u.source_id=''jobkorea''
 $query$;
END ' THEN

  CREATE TEMP VIEW source_query_expected_jobkorea AS
SELECT i.run_id,i.code AS issue,i.locator||CASE WHEN i.field<>'' THEN ':'||i.field ELSE '' END AS location
FROM ingestion.jobkorea_issue i WHERE i.severity='ERROR'
UNION ALL
SELECT u.run_id,'JOBKOREA_IMPORT_PROVENANCE_MISSING','' FROM ingestion.run u
WHERE u.source_id='jobkorea' AND NOT EXISTS(SELECT 1 FROM ingestion.jobkorea_import i WHERE i.run_id=u.run_id)
UNION ALL
SELECT i.run_id,'JOBKOREA_IMPORT_METADATA_CONFLICT','' FROM ingestion.jobkorea_import i
JOIN ingestion.run u USING(run_id)
WHERE u.source_id<>'jobkorea' OR u.mode<>'REPLAY' OR u.parser_version<>i.parser_version OR u.policy_revision<>i.policy_revision
 OR i.policy_revision<>'2026-10-07.1'
 OR (i.file_format='JSON_ARRAY' AND (i.parser_version<>'hop-jobkorea-v1'
  OR i.raw_path<>'jobkorea/'||i.file_sha256||'/source.json'
  OR i.run_id<>'jobkorea-'||encode(sha256(convert_to('hop-jobkorea-v1:2026-10-07.1:'||i.file_sha256,'UTF8')),'hex')))
 OR (i.file_format='NDJSON' AND (i.parser_version<>'hop-jobkorea-ndjson-v1'
  OR i.raw_path<>'jobkorea/'||i.file_sha256||'/source.ndjson'
  OR i.run_id<>'jobkorea-ndjson-'||encode(sha256(convert_to('hop-jobkorea-ndjson-v1:2026-10-07.1:'||i.file_sha256,'UTF8')),'hex')))
 OR i.scope<>'FILE_ONLY' OR i.provider_complete
UNION ALL
SELECT i.run_id,'JOBKOREA_FILE_NOT_PROCESSED','' FROM ingestion.jobkorea_import i
WHERE NOT i.loaded OR i.processed_at IS NULL OR i.payload_sha256 IS DISTINCT FROM i.file_sha256 OR i.error_code IS NOT NULL
UNION ALL
SELECT i.run_id,'JOBKOREA_ROW_MANIFEST_CONFLICT','' FROM ingestion.jobkorea_import i
WHERE i.loaded AND i.row_manifest_sha256 IS DISTINCT FROM ingestion.jobkorea_row_manifest(i.run_id)
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCAL_DOCUMENT_CONFLICT',i.document_id FROM ingestion.jobkorea_import i
LEFT JOIN ingestion.document d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE d.document_id IS NULL OR d.transport<>'LOCAL_FILE' OR d.http_status IS NOT NULL OR d.provider_result IS NOT NULL
 OR d.raw_sha256<>i.file_sha256 OR d.byte_length<>i.byte_length OR d.raw_path<>i.raw_path OR d.encoding<>'UTF-8'
 OR d.retrieved_at<>i.received_at OR d.partition_id<>'local-file' OR d.page_no<>1 OR d.confirmation_no<>0 OR d.attempt_no<>1
 OR NOT d.selected OR d.verified_at IS NULL
 OR d.item_count IS NULL OR d.item_count=0 OR d.declared_total IS DISTINCT FROM d.item_count
 OR d.effective_page<>1 OR d.effective_page_size IS DISTINCT FROM d.item_count
 OR (SELECT count(*) FROM ingestion.document x WHERE x.run_id=i.run_id)<>1
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCAL_PARTITION_CONFLICT','local-file' FROM ingestion.jobkorea_import i
LEFT JOIN ingestion.partition p ON p.run_id=i.run_id AND p.partition_id='local-file'
LEFT JOIN ingestion.document d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE p.partition_id IS NULL OR p.kind<>'FILE' OR p.expected_total IS DISTINCT FROM d.item_count
 OR p.page_size IS DISTINCT FROM d.item_count
 OR p.request_context IS DISTINCT FROM '{"transport":"LOCAL_FILE","scope":"FILE_ONLY","provider_complete":false,"absence_is_closure":false}'::jsonb
 OR (SELECT count(*) FROM ingestion.partition x WHERE x.run_id=i.run_id)<>1
UNION ALL
SELECT r.run_id,'JOBKOREA_RECORD_NORMALIZATION_CONFLICT',r.locator
FROM ingestion.record r JOIN ingestion.run u USING(run_id)
JOIN ingestion.jobkorea_import i USING(run_id)
CROSS JOIN LATERAL ingestion.normalize_jobkorea_row(r.source_payload,r.locator) n
WHERE u.source_id='jobkorea' AND (r.normalized IS DISTINCT FROM n.normalized OR r.field_lineage IS DISTINCT FROM n.field_lineage
 OR r.quality_flags IS DISTINCT FROM n.quality_flags OR jsonb_array_length(n.errors)>0
 OR r.source_record_id IS DISTINCT FROM r.normalized->>'posting_id'
 OR (i.file_format='JSON_ARRAY' AND r.locator !~ '^/(0|[1-9][0-9]*)$')
 OR (i.file_format='NDJSON' AND r.locator !~ '^line:[1-9][0-9]*$')
 OR r.document_id<>'local-json')
UNION ALL
SELECT i.run_id,'JOBKOREA_LOCATOR_ACCOUNTING_CONFLICT','' FROM ingestion.jobkorea_import i
JOIN ingestion.document d ON d.run_id=i.run_id AND d.document_id=i.document_id
WHERE i.file_format='JSON_ARRAY' AND d.item_count IS NOT NULL AND (
 (SELECT count(DISTINCT locator) FROM (
  SELECT locator FROM ingestion.record r WHERE r.run_id=i.run_id
  UNION ALL SELECT locator FROM ingestion.rejected_row r WHERE r.run_id=i.run_id) x)<>d.item_count
 OR EXISTS(SELECT 1 FROM (
  SELECT locator FROM ingestion.record r WHERE r.run_id=i.run_id
  UNION ALL SELECT locator FROM ingestion.rejected_row r WHERE r.run_id=i.run_id) x
  WHERE x.locator !~ '^/(0|[1-9][0-9]*)$' OR length(x.locator)>12
   OR CASE WHEN x.locator ~ '^/(0|[1-9][0-9]*)$' AND length(x.locator)<=12
     THEN substring(x.locator FROM 2)::bigint>=d.item_count ELSE true END))
UNION ALL
SELECT u.run_id,'JOBKOREA_UNEXPECTED_HTTP_REQUEST','' FROM ingestion.run u
WHERE u.source_id='jobkorea' AND EXISTS(SELECT 1 FROM ingestion.request_attempt a WHERE a.run_id=u.run_id)
UNION ALL
SELECT u.run_id,'JOBKOREA_UNEXPECTED_DEPENDENCY','' FROM ingestion.run u
WHERE u.source_id='jobkorea' AND EXISTS(SELECT 1 FROM ingestion.dependency a WHERE a.run_id=u.run_id)
UNION ALL
SELECT * FROM ingestion.jobkorea_cs_collision_issue()
UNION ALL SELECT * FROM ingestion.jobkorea_ndjson_validation_issue();

  IF pg_get_viewdef('source_query_expected_jobkorea'::regclass,true)
   IS DISTINCT FROM pg_get_viewdef('ingestion.jobkorea_validation_issue'::regclass,true)
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_CANONICAL_JOBKOREA_VALIDATION_DRIFT'; END IF;
  DROP VIEW source_query_expected_jobkorea;
  jk_hash:=md5(pg_get_viewdef('ingestion.jobkorea_validation_issue'::regclass,true));
  hook_hash:=md5(pg_get_functiondef('ingestion.local_file_validation_issue()'::regprocedure));
  nd_hash:=md5(pg_get_functiondef('ingestion.jobkorea_ndjson_validation_issue()'::regprocedure));
  collision_hash:=md5(pg_get_functiondef('ingestion.jobkorea_cs_collision_issue()'::regprocedure));
 END IF;
 local_wrapper:=$definition$
CREATE OR REPLACE FUNCTION ingestion.source_graph_local_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text) LANGUAGE plpgsql STABLE SET jit=off AS $body$
BEGIN
 IF __HOOK_HASH__ IS NOT NULL
  AND md5(pg_get_functiondef(to_regprocedure('ingestion.local_file_validation_issue()')))=__HOOK_HASH__
  AND md5(pg_get_viewdef(to_regclass('ingestion.jobkorea_validation_issue'),true))=__JK_HASH__
  AND md5(pg_get_functiondef(to_regprocedure('ingestion.jobkorea_ndjson_validation_issue()')))=__ND_HASH__
  AND md5(pg_get_functiondef(to_regprocedure('ingestion.jobkorea_cs_collision_issue()')))=__COLLISION_HASH__ THEN
  RETURN QUERY EXECUTE 'SELECT * FROM ingestion.source_graph_jobkorea_validation_issue($1)' USING jobs;
 ELSE
  RETURN QUERY SELECT v.* FROM ingestion.local_file_validation_issue() v WHERE v.run_id=jobs;
 END IF;
END $body$;
$definition$;
 EXECUTE replace(replace(replace(replace(local_wrapper,'__HOOK_HASH__',quote_nullable(hook_hash)),
  '__JK_HASH__',quote_nullable(jk_hash)),'__ND_HASH__',quote_nullable(nd_hash)),
  '__COLLISION_HASH__',quote_nullable(collision_hash));
END $bind_rules$;


DO $selection_contract$ DECLARE definition text; BEGIN
CREATE TEMP VIEW source_query_expected_selection AS
SELECT r.*, u.source_id
FROM ingestion.record r
JOIN ingestion.run u USING (run_id)
