 IS DISTINCT FROM pg_get_viewdef('ingestion.graph_reference'::regclass,true)
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_CANONICAL_SELECTION_DRIFT'; END IF;
 END IF;
