 IF pg_get_viewdef('source_query_expected_selection'::regclass,true)
 IS DISTINCT FROM pg_get_viewdef('ingestion.source_graph_reference'::regclass,true)
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_CANONICAL_SELECTION_DRIFT'; END IF;
 END IF;
 DROP VIEW source_query_expected_selection;

CREATE TEMP VIEW source_query_expected_selection AS
SELECT g.run_id,g.id AS record_id,g.source_record_id,
 encode(sha256(convert_to(r.normalized::text,'UTF8')),'hex') AS normalized_sha256,
 encode(sha256(convert_to(g.facts_json,'UTF8')),'hex') AS facts_sha256,
 d.raw_sha256 AS document_sha256,
 encode(sha256(convert_to(jsonb_build_object('source_payload',r.source_payload,
 'normalized',r.normalized,'field_lineage',r.field_lineage,'quality_flags',r.quality_flags,
 'document_id',r.document_id,'locator',r.locator,'source_record_id',r.source_record_id,
 'document_sha256',d.raw_sha256,'facts_json',g.facts_json)::text,'UTF8')),'hex') AS content_sha256
FROM ingestion.graph_record g JOIN ingestion.ready_record r USING(run_id,record_id)
JOIN ingestion.document d USING(run_id,document_id);
 IF pg_get_viewdef('source_query_expected_selection'::regclass,true)
 IS DISTINCT FROM pg_get_viewdef('ingestion.source_graph_live_record_evidence'::regclass,true)
 THEN
 -- pg_dump/restore can add aliases to unnamed UNION literals.
 -- Parse exactly one canonical deparse round trip as the second
 -- accepted form, without discarding any predicates or branches.
 EXECUTE 'CREATE OR REPLACE TEMP VIEW source_query_expected_selection AS '
 ||pg_get_viewdef('source_query_expected_selection'::regclass,true);
 IF pg_get_viewdef('source_query_expected_selection'::regclass,true)
 IS DISTINCT FROM pg_get_viewdef('ingestion.source_graph_live_record_evidence'::regclass,true)
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_CANONICAL_SELECTION_DRIFT'; END IF;
 END IF;
 DROP VIEW source_query_expected_selection;
definition:=$definition$
CREATE OR REPLACE FUNCTION ingestion.source_graph_assert_query_contract() RETURNS void
LANGUAGE plpgsql STABLE SET jit=off AS $body$ BEGIN
 IF md5(pg_get_viewdef(to_regclass('ingestion.ready_record'),true))
 IS DISTINCT FROM __VIEW0__
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_QUERY_CONTRACT_CHANGED'; END IF;
 IF md5(pg_get_viewdef(to_regclass('ingestion.graph_record'),true))
 IS DISTINCT FROM __VIEW1__
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_QUERY_CONTRACT_CHANGED'; END IF;
 IF md5(pg_get_viewdef(to_regclass('ingestion.graph_reference'),true))
 IS DISTINCT FROM __VIEW2__
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_QUERY_CONTRACT_CHANGED'; END IF;
 IF md5(pg_get_viewdef(to_regclass('ingestion.source_graph_reference'),true))
 IS DISTINCT FROM __VIEW3__
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_QUERY_CONTRACT_CHANGED'; END IF;
 IF md5(pg_get_viewdef(to_regclass('ingestion.source_graph_live_record_evidence'),true))
 IS DISTINCT FROM __VIEW4__
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_QUERY_CONTRACT_CHANGED'; END IF;
END $body$;
$definition$;
 definition:=replace(definition,'__VIEW0__',
 quote_literal(md5(pg_get_viewdef('ingestion.ready_record'::regclass,true))));
 definition:=replace(definition,'__VIEW1__',
 quote_literal(md5(pg_get_viewdef('ingestion.graph_record'::regclass,true))));
 definition:=replace(definition,'__VIEW2__',
 quote_literal(md5(pg_get_viewdef('ingestion.graph_reference'::regclass,true))));
 definition:=replace(definition,'__VIEW3__',
 quote_literal(md5(pg_get_viewdef('ingestion.source_graph_reference'::regclass,true))));
 definition:=replace(definition,'__VIEW4__',
 quote_literal(md5(pg_get_viewdef('ingestion.source_graph_live_record_evidence'::regclass,true))));
 EXECUTE definition;
END $selection_contract$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_manifest(jobs text,live boolean DEFAULT false)
RETURNS TABLE(record_count bigint,reference_count bigint,content_sha256 text)
LANGUAGE plpgsql STABLE SET jit=off AS $$
BEGIN
 IF live THEN PERFORM ingestion.source_graph_assert_query_contract(); END IF;
 RETURN QUERY
 WITH target AS MATERIALIZED (
 SELECT u.run_id,u.source_id FROM ingestion.run u WHERE live AND u.run_id=jobs
 AND u.state='READY' AND u.mode<>'SMOKE'
), selected_documents AS MATERIALIZED (
 SELECT d.* FROM ingestion.document d JOIN target u USING(run_id) WHERE d.selected
), ready AS MATERIALIZED (
 SELECT r.*,u.source_id FROM ingestion.record r JOIN target u USING(run_id)
 JOIN selected_documents d USING(run_id,document_id)
), live_records AS (
SELECT r.run_id,g.id AS record_id,g.source_record_id,
 encode(sha256(convert_to(r.normalized::text,'UTF8')),'hex') AS normalized_sha256,
 encode(sha256(convert_to(g.facts_json,'UTF8')),'hex') AS facts_sha256,
 d.raw_sha256 AS document_sha256,
 encode(sha256(convert_to(jsonb_build_object('source_payload',r.source_payload,
 'normalized',r.normalized,'field_lineage',r.field_lineage,'quality_flags',r.quality_flags,
 'document_id',r.document_id,'locator',r.locator,'source_record_id',r.source_record_id,
 'document_sha256',d.raw_sha256,'facts_json',g.facts_json)::text,'UTF8')),'hex') AS content_sha256
FROM ready r CROSS JOIN LATERAL (SELECT 'hop:'||r.run_id||':'||r.record_id::text AS id,
 r.source_record_id,(CASE WHEN r.source_id='jobkorea' THEN ingestion.jobkorea_graph_facts(r.normalized)
 ELSE r.normalized-ARRAY['definition','eligibility_text','disqualification_text','preference_text',
 'selection_text','address','website','source_url'] END)::text AS facts_json) g
 JOIN selected_documents d USING(run_id,document_id)
), live_members AS (
SELECT 'hop:' || r.run_id || ':' || r.record_id::text AS record_id, r.run_id,
       ref.namespace || ':' || ref.code AS identity_id, ref.kind, ref.code, ref.field
FROM ready r
CROSS JOIN LATERAL (
    SELECT 'ncs:occupation' AS namespace, 'Occupation' AS kind,
           r.normalized->>'occupation_code' AS code, 'occupation_code' AS field
    WHERE r.source_id IN ('ncs_career_path', 'ncs_competency')
    UNION ALL
    SELECT 'ncs:unversioned-unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_career_path'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'code', 'code'
    WHERE r.source_id = 'ncs_competency'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_qualification'
    UNION ALL
    SELECT 'qnet:qualification', 'Qualification', r.normalized->>'qualification_code', 'qualification_code'
    WHERE r.source_id IN ('ncs_qualification', 'qnet_schedule')
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'code', 'code'
    WHERE r.source_id = 'alio_organization'
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'organization_code', 'organization_code'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'job-alio:posting', 'JobPosting', r.normalized->>'posting_id', 'posting_id'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'source:posting:nara_job', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'nara_job'
    UNION ALL
    SELECT 'source:posting:jobkorea', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'jobkorea'
) ref
WHERE ref.code IS NOT NULL
UNION ALL
SELECT 'hop:'||r.run_id||':'||r.record_id::text,r.run_id,
 'qnet:exam-session:'||encode(sha256(convert_to(r.source_record_id,'UTF8')),'hex'),
 'ExamSession',r.source_record_id,'source_record_id' FROM ready r WHERE r.source_id='qnet_schedule'
), records AS MATERIALIZED (
 SELECT * FROM live_records WHERE live AND run_id=jobs
 UNION ALL SELECT * FROM ingestion.source_graph_record_evidence WHERE NOT live AND run_id=jobs
 ), members AS MATERIALIZED (
 SELECT run_id,record_id,identity_id,field,kind,code FROM live_members WHERE live AND run_id=jobs
 UNION ALL SELECT * FROM ingestion.source_graph_membership WHERE NOT live AND run_id=jobs
 )
 SELECT (SELECT count(*) FROM records),(SELECT count(*) FROM members),
 ingestion.source_graph_digest(
 (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY record_id),'[]') FROM records r),
 (SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY record_id,identity_id,field),'[]') FROM members m)
 );
END $$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_run_is_valid(jobs text)
RETURNS boolean LANGUAGE plpgsql STABLE SET jit=off AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM ingestion.run WHERE run_id=jobs AND state='READY' AND mode<>'SMOKE')
 THEN RETURN false; END IF;
 RETURN NOT EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(jobs));
END $$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_projection_guard() RETURNS trigger
LANGUAGE plpgsql SET jit=off AS $$
DECLARE m record;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.run_id,NEW.source_id,NEW.loader_version,NEW.record_count,NEW.reference_count,NEW.content_sha256)
   IS DISTINCT FROM (OLD.run_id,OLD.source_id,OLD.loader_version,OLD.record_count,OLD.reference_count,OLD.content_sha256)
  THEN RAISE EXCEPTION 'IMMUTABLE_SOURCE_GRAPH_SNAPSHOT_PROOF'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM ingestion.run WHERE run_id=NEW.run_id AND source_id=NEW.source_id AND state='READY' AND mode<>'SMOKE')
   OR EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(NEW.run_id))
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
  SELECT * INTO m FROM ingestion.source_graph_manifest(NEW.run_id,true);
  IF (NEW.record_count,NEW.reference_count,NEW.content_sha256) IS DISTINCT FROM (m.record_count,m.reference_count,m.content_sha256)
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_LIVE_CONTENT_MISMATCH'; END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION ingestion.assert_source_graph_content(jobs text) RETURNS void
LANGUAGE plpgsql SET jit=off AS $$
DECLARE p ingestion.source_graph_projection; m record;
BEGIN
 SELECT * INTO p FROM ingestion.source_graph_projection WHERE run_id=jobs;
 IF NOT FOUND THEN RAISE EXCEPTION 'SOURCE_GRAPH_PROJECTION_MISSING'; END IF;
 SELECT * INTO m FROM ingestion.source_graph_manifest(jobs);
 IF (p.record_count,p.reference_count,p.content_sha256) IS DISTINCT FROM (m.record_count,m.reference_count,m.content_sha256)
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_EVIDENCE_MISMATCH'; END IF;
 -- A retained live source must still be accepted and byte-for-byte equivalent.
 -- After explicitly archived source cleanup, the immutable captured proof stays.
 IF EXISTS(SELECT 1 FROM ingestion.run WHERE run_id=jobs) THEN
  IF NOT EXISTS(SELECT 1 FROM ingestion.run WHERE run_id=jobs AND state='READY' AND mode<>'SMOKE')
   OR EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(jobs))
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
  SELECT * INTO m FROM ingestion.source_graph_manifest(jobs,true);
  IF (p.record_count,p.reference_count,p.content_sha256) IS DISTINCT FROM (m.record_count,m.reference_count,m.content_sha256)
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_LIVE_CONTENT_MISMATCH'; END IF;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION ingestion.begin_source_graph_projection(jobs text) RETURNS boolean
LANGUAGE plpgsql SET jit=off AS $$
DECLARE u ingestion.run; m record;
BEGIN
 SELECT * INTO u FROM ingestion.run WHERE run_id=jobs AND state='READY' AND mode<>'SMOKE';
 IF NOT FOUND OR EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(jobs))
 THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
 INSERT INTO ingestion.source_graph_record_evidence SELECT * FROM ingestion.source_graph_live_record_evidence
 WHERE run_id=jobs ON CONFLICT DO NOTHING;
 INSERT INTO ingestion.source_graph_membership SELECT run_id,record_id,identity_id,field,kind,code FROM ingestion.source_graph_reference
 WHERE run_id=jobs ON CONFLICT DO NOTHING;
 SELECT * INTO m FROM ingestion.source_graph_manifest(jobs,true);
 INSERT INTO ingestion.source_graph_projection(run_id,source_id,state,loader_version,record_count,reference_count,content_sha256,started_at)
 VALUES(jobs,u.source_id,'LOADING','hop-graph-batchfree-v1',m.record_count,m.reference_count,m.content_sha256,clock_timestamp())
 ON CONFLICT(run_id) DO UPDATE SET state='LOADING',verified_at=NULL,error_code=NULL,started_at=clock_timestamp();
 PERFORM ingestion.assert_source_graph_content(jobs);
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION ingestion.posting_ingestion_insert_guard() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM inserted_observations) THEN RETURN NULL; END IF;
 -- The Boolean test preserves a run-correlated validator SubPlan even before
 -- source statistics exist, avoiding joins across unrelated source histories.
 IF EXISTS(SELECT 1 FROM (SELECT DISTINCT run_id FROM inserted_observations) n
  WHERE (EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(n.run_id) v)) IS TRUE)
 THEN RAISE EXCEPTION 'POSTING_DATE_RUN_VALIDATION_FAILED'; END IF;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION ingestion.jobkorea_collection_time_guard() RETURNS trigger
LANGUAGE plpgsql AS $$ DECLARE receipt record; BEGIN
 PERFORM retention.gate();
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_JOBKOREA_COLLECTION_TIME_EVIDENCE'; END IF;
 IF to_regclass('ingestion.jobkorea_import') IS NULL THEN RAISE EXCEPTION 'JOBKOREA_IMPORT_RECEIPT_REQUIRED'; END IF;
 EXECUTE 'SELECT i.file_sha256,i.imported_at,i.scraped_at FROM ingestion.jobkorea_import i
  JOIN ingestion.run u USING(run_id) WHERE i.run_id=$1 AND u.source_id=''jobkorea''
  AND u.state=''READY'' AND u.mode=''REPLAY'' AND i.loaded AND i.error_code IS NULL
  AND NOT EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(u.run_id) v)'
 INTO receipt USING NEW.run_id;
 IF receipt.file_sha256 IS NULL OR receipt.file_sha256 IS DISTINCT FROM NEW.file_sha256
  OR NEW.scraped_at>receipt.imported_at OR NEW.scraped_at>clock_timestamp()
  OR (receipt.scraped_at IS NOT NULL AND receipt.scraped_at IS DISTINCT FROM NEW.scraped_at)
  OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.reported_timezone)
 THEN RAISE EXCEPTION 'INVALID_JOBKOREA_COLLECTION_TIME_EVIDENCE'; END IF;
 NEW.recorded_at:=clock_timestamp();
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION ingestion.record_posting_ingestion_observations(jobs text)
RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE added bigint; source text; BEGIN
 PERFORM retention.gate();
 SELECT u.source_id INTO source FROM ingestion.run u
  WHERE u.run_id=jobs AND u.state='READY' AND u.mode<>'SMOKE';
 IF jobs IS NULL OR jobs='LATEST' OR source IS NULL
 THEN RAISE EXCEPTION 'POSTING_DATES_REQUIRE_EXACT_READY_RUN'; END IF;
 IF source NOT IN('job_alio','nara_job','jobkorea') THEN RETURN 0; END IF;
 IF EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(jobs) v)
 THEN RAISE EXCEPTION 'POSTING_DATES_REQUIRE_EXACT_READY_RUN'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('posting-ingestion-observations',0));
 WITH source_rows AS MATERIALIZED (
  SELECT r.source_id,r.run_id,r.normalized->>'posting_id' AS posting,
   min(r.record_id) AS evidence_record_id
  FROM ingestion.ready_record r WHERE r.source_id=source AND r.normalized->>'posting_id' IS NOT NULL
  GROUP BY r.source_id,r.run_id,r.normalized->>'posting_id'
 ), matched AS MATERIALIZED (
  -- Mark each posting's accepted historical occurrences in one ordered pass.
  -- Matching a freshly imported wanted set with a join can underestimate its
  -- cardinality and compare every posting against every source row.
  SELECT s.*,bool_or(s.run_id=jobs) OVER(PARTITION BY s.source_id,s.posting) AS in_target
  FROM source_rows s
 ), valid_runs AS MATERIALIZED (
  SELECT u.run_id FROM ingestion.run u WHERE u.state='READY' AND u.mode<>'SMOKE'
   AND u.source_id=source
   -- Keep validation correlated to each candidate run. An unfenced NOT EXISTS
   -- can pull up the expanded validator and compare unrelated source records
   -- quadratically when a fresh import has not yet been autoanalyzed.
   AND (NOT EXISTS(SELECT 1 FROM ingestion.source_graph_validation_issue(u.run_id) v)) IS TRUE
 ), selected AS MATERIALIZED (
  SELECT r.source_id,r.posting,r.run_id,r.evidence_record_id
  FROM matched r JOIN valid_runs u USING(run_id) WHERE r.in_target
 ), events AS MATERIALIZED (
  SELECT x.run_id,e.* FROM (SELECT DISTINCT run_id FROM selected) x
  CROSS JOIN LATERAL ingestion.posting_ingestion_run_event(x.run_id) e
 )
 INSERT INTO ingestion.posting_ingestion_observation
 (identity_id,source_id,source_posting_id,run_id,evidence_record_id,ingested_at,ingestion_time_basis,receipt_scraped_at)
 SELECT ingestion.posting_identity(s.source_id,s.posting),s.source_id,s.posting,s.run_id,s.evidence_record_id,
  e.ingested_at,e.ingestion_time_basis,e.receipt_scraped_at
 FROM selected s JOIN events e USING(run_id)
 WHERE NOT EXISTS(SELECT 1 FROM ingestion.posting_ingestion_observation prior
  WHERE prior.identity_id=ingestion.posting_identity(s.source_id,s.posting) AND prior.run_id=s.run_id)
 ON CONFLICT(identity_id,run_id) DO NOTHING;
 GET DIAGNOSTICS added=ROW_COUNT;
 IF EXISTS(SELECT 1 FROM ingestion.ready_record r WHERE r.run_id=jobs
  AND r.source_id IN('job_alio','nara_job','jobkorea') AND r.normalized->>'posting_id' IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM ingestion.posting_ingestion_observation o WHERE o.run_id=jobs
   AND o.identity_id=ingestion.posting_identity(r.source_id,r.normalized->>'posting_id')))
 THEN RAISE EXCEPTION 'POSTING_DATE_OBSERVATION_MISSING'; END IF;
 RETURN added;
END $$;

CREATE OR REPLACE FUNCTION ingestion.graph_source_edges(jobs text)
RETURNS TABLE(owner_id text,source_id text,source_run_id text,source_record_id text,
 from_id text,to_id text,edge_kind text,edge_key text,edge_facts_json text)
LANGUAGE plpgsql STABLE SET jit=off AS $$
#variable_conflict use_column
BEGIN
 PERFORM ingestion.source_graph_assert_query_contract();
 RETURN QUERY
 WITH target_source AS MATERIALIZED(SELECT source_id FROM ingestion.run WHERE run_id=jobs),
ready_runs AS MATERIALIZED(SELECT u.run_id,u.source_id,u.created_at FROM ingestion.run u
 WHERE u.state='READY' AND u.mode<>'SMOKE'
 AND (jobs='ALL_CHECKPOINTED'
 OR NOT EXISTS(SELECT 1 FROM target_source)
 OR u.source_id NOT IN('alio_organization','job_alio','nara_job','jobkorea','ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 OR EXISTS(SELECT 1 FROM target_source t WHERE t.source_id=u.source_id
 OR t.source_id NOT IN('alio_organization','job_alio','nara_job','jobkorea','ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 OR (t.source_id IN('alio_organization','job_alio') AND u.source_id IN('alio_organization','job_alio'))
 OR (t.source_id IN('ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 AND u.source_id IN('ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule'))))),
selected_documents AS MATERIALIZED(SELECT d.run_id,d.document_id
 FROM ingestion.document d JOIN ready_runs u USING(run_id) WHERE d.selected),
records AS MATERIALIZED(SELECT r.run_id,r.record_id,u.source_id,r.source_record_id,r.normalized,u.created_at
 FROM ingestion.record r JOIN ready_runs u USING(run_id)
 JOIN selected_documents d USING(run_id,document_id)),
raw_refs AS (
SELECT 'hop:' || r.run_id || ':' || r.record_id::text AS record_id, r.run_id,
       ref.namespace || ':' || ref.code AS identity_id, ref.kind, ref.code, ref.field
FROM records r
CROSS JOIN LATERAL (
    SELECT 'ncs:occupation' AS namespace, 'Occupation' AS kind,
           r.normalized->>'occupation_code' AS code, 'occupation_code' AS field
    WHERE r.source_id IN ('ncs_career_path', 'ncs_competency')
    UNION ALL
    SELECT 'ncs:unversioned-unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_career_path'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'code', 'code'
    WHERE r.source_id = 'ncs_competency'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_qualification'
    UNION ALL
    SELECT 'qnet:qualification', 'Qualification', r.normalized->>'qualification_code', 'qualification_code'
    WHERE r.source_id IN ('ncs_qualification', 'qnet_schedule')
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'code', 'code'
    WHERE r.source_id = 'alio_organization'
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'organization_code', 'organization_code'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'job-alio:posting', 'JobPosting', r.normalized->>'posting_id', 'posting_id'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'source:posting:nara_job', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'nara_job'
    UNION ALL
    SELECT 'source:posting:jobkorea', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'jobkorea'
) ref
WHERE ref.code IS NOT NULL
UNION ALL
SELECT 'hop:'||r.run_id||':'||r.record_id::text,r.run_id,
 'qnet:exam-session:'||encode(sha256(convert_to(r.source_record_id,'UTF8')),'hex'),
 'ExamSession',r.source_record_id,'source_record_id' FROM records r WHERE r.source_id='qnet_schedule'
),
refs AS MATERIALIZED(SELECT q.*,substring(q.record_id from '[^:]+$')::bigint AS numeric_record_id FROM raw_refs q),
 target_assessments AS MATERIALIZED(SELECT u.run_id,
 ingestion.source_graph_run_is_valid(u.run_id) AS valid FROM ready_runs u
 WHERE u.run_id=jobs OR (jobs='ALL_CHECKPOINTED' AND EXISTS(SELECT 1 FROM ingestion.graph_export g WHERE g.run_id=u.run_id))),
 touched AS MATERIALIZED(SELECT DISTINCT q.identity_id FROM refs q
 JOIN target_assessments a USING(run_id) WHERE a.valid),
needed_edge_runs AS MATERIALIZED(SELECT DISTINCT q.run_id FROM refs q JOIN touched t USING(identity_id)),
edge_assessments AS MATERIALIZED(SELECT * FROM target_assessments UNION ALL
 SELECT u.run_id,ingestion.source_graph_run_is_valid(u.run_id) FROM ready_runs u
 JOIN needed_edge_runs n USING(run_id) WHERE NOT EXISTS(SELECT 1 FROM target_assessments a WHERE a.run_id=u.run_id)),

 owners AS MATERIALIZED(
 SELECT DISTINCT ON(q.identity_id,r.source_id) q.identity_id,r.source_id,r.run_id
 FROM refs q JOIN touched t USING(identity_id)
 JOIN edge_assessments a ON a.run_id=q.run_id AND a.valid
 JOIN records r ON q.run_id=r.run_id AND r.record_id=q.numeric_record_id
 WHERE ((r.source_id='job_alio' AND q.kind='JobPosting')
 OR (r.source_id='ncs_competency' AND q.kind='Competency')
 OR (r.source_id='ncs_career_path' AND q.kind='Occupation')
 OR (r.source_id='ncs_qualification' AND q.kind='Competency')
 OR (r.source_id='qnet_schedule' AND q.kind='ExamSession'))
 ORDER BY q.identity_id,r.source_id,r.created_at DESC,r.run_id DESC
 ), pairs AS(
 SELECT o.identity_id AS owner_id,r.source_id,r.run_id,r.source_record_id,
 CASE WHEN r.source_id='qnet_schedule' THEN target.identity_id ELSE o.identity_id END AS from_id,
 CASE WHEN r.source_id='qnet_schedule' THEN o.identity_id ELSE target.identity_id END AS to_id,
 CASE r.source_id WHEN 'job_alio' THEN 'EMPLOYER' WHEN 'ncs_competency' THEN 'CLASSIFIED_AS'
 WHEN 'ncs_career_path' THEN 'HAS_CAREER_COMPETENCY' WHEN 'ncs_qualification' THEN 'QUALIFICATION_MAPPING'
 WHEN 'qnet_schedule' THEN 'HAS_EXAM_SESSION' END AS edge_kind,
 (CASE WHEN r.source_id='jobkorea' THEN ingestion.jobkorea_graph_facts(r.normalized)
 ELSE r.normalized-ARRAY['definition','eligibility_text','disqualification_text','preference_text','selection_text','address','website','source_url'] END)::text AS facts_json
 FROM owners o JOIN refs self ON self.run_id=o.run_id AND self.identity_id=o.identity_id
 JOIN records r ON r.run_id=self.run_id AND r.record_id=self.numeric_record_id
 JOIN refs target ON target.run_id=self.run_id AND target.numeric_record_id=self.numeric_record_id
 AND ((r.source_id='job_alio' AND target.kind='Organization')
 OR (r.source_id='ncs_competency' AND target.kind='Occupation')
 OR (r.source_id='ncs_career_path' AND target.kind='Competency')
 OR (r.source_id='ncs_qualification' AND target.kind='Qualification')
 OR (r.source_id='qnet_schedule' AND target.kind='Qualification'))
 ), dedup AS(
 SELECT DISTINCT ON(owner_id,source_id,from_id,to_id,edge_kind,
 CASE WHEN source_id IN('job_alio','ncs_competency') THEN '' ELSE source_record_id END) * FROM pairs
 ORDER BY owner_id,source_id,from_id,to_id,edge_kind,
 CASE WHEN source_id IN('job_alio','ncs_competency') THEN '' ELSE source_record_id END,source_record_id DESC
 )
 SELECT owner_id,source_id,run_id,source_record_id,from_id,to_id,edge_kind,
 encode(sha256(convert_to(jsonb_build_array(source_id,owner_id,from_id,to_id,edge_kind,
 CASE WHEN source_id IN('job_alio','ncs_competency') THEN '' ELSE source_record_id END)::text,'UTF8')),'hex'),facts_json
 FROM dedup ORDER BY owner_id,edge_kind,to_id;
END $$;

CREATE OR REPLACE FUNCTION ingestion.graph_source_entities(jobs text)
RETURNS TABLE(identity_id text,kind text,code text,entity_name text,entity_title text,
 name_source_run_id text,name_source_record_id text,source_id text,source_run_id text,
 source_record_id text,source_created_at text,source_facts_json text,source_facts_sha256 text)
LANGUAGE plpgsql SET jit=off AS $$
#variable_conflict use_column
BEGIN
 PERFORM ingestion.source_graph_assert_query_contract();
 IF jobs='ALL_CHECKPOINTED' THEN
  IF EXISTS(SELECT 1 FROM ingestion.graph_export g JOIN ingestion.run u USING(run_id)
   WHERE NOT ingestion.source_graph_run_is_valid(u.run_id))
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
 ELSE
  IF NOT ingestion.source_graph_run_is_valid(jobs)
  THEN RAISE EXCEPTION 'SOURCE_GRAPH_REQUIRES_EXACT_READY_RUN'; END IF;
 END IF;
 RETURN QUERY
 WITH target_source AS MATERIALIZED(SELECT source_id FROM ingestion.run WHERE run_id=jobs),
ready_runs AS MATERIALIZED(SELECT u.run_id,u.source_id,u.created_at FROM ingestion.run u
 WHERE u.state='READY' AND u.mode<>'SMOKE'
 AND (jobs='ALL_CHECKPOINTED'
 OR NOT EXISTS(SELECT 1 FROM target_source)
 OR u.source_id NOT IN('alio_organization','job_alio','nara_job','jobkorea','ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 OR EXISTS(SELECT 1 FROM target_source t WHERE t.source_id=u.source_id
 OR t.source_id NOT IN('alio_organization','job_alio','nara_job','jobkorea','ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 OR (t.source_id IN('alio_organization','job_alio') AND u.source_id IN('alio_organization','job_alio'))
 OR (t.source_id IN('ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule')
 AND u.source_id IN('ncs_career_path','ncs_competency','ncs_qualification','qnet_schedule'))))),
selected_documents AS MATERIALIZED(SELECT d.run_id,d.document_id
 FROM ingestion.document d JOIN ready_runs u USING(run_id) WHERE d.selected),
records AS MATERIALIZED(SELECT r.run_id,r.record_id,u.source_id,r.source_record_id,r.normalized,u.created_at
 FROM ingestion.record r JOIN ready_runs u USING(run_id)
 JOIN selected_documents d USING(run_id,document_id)),
raw_refs AS (
SELECT 'hop:' || r.run_id || ':' || r.record_id::text AS record_id, r.run_id,
       ref.namespace || ':' || ref.code AS identity_id, ref.kind, ref.code, ref.field
FROM records r
CROSS JOIN LATERAL (
    SELECT 'ncs:occupation' AS namespace, 'Occupation' AS kind,
           r.normalized->>'occupation_code' AS code, 'occupation_code' AS field
    WHERE r.source_id IN ('ncs_career_path', 'ncs_competency')
    UNION ALL
    SELECT 'ncs:unversioned-unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_career_path'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'code', 'code'
    WHERE r.source_id = 'ncs_competency'
    UNION ALL
    SELECT 'ncs:unit', 'Competency', r.normalized->>'competency_code', 'competency_code'
    WHERE r.source_id = 'ncs_qualification'
    UNION ALL
    SELECT 'qnet:qualification', 'Qualification', r.normalized->>'qualification_code', 'qualification_code'
    WHERE r.source_id IN ('ncs_qualification', 'qnet_schedule')
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'code', 'code'
    WHERE r.source_id = 'alio_organization'
    UNION ALL
    SELECT 'alio:organization', 'Organization', r.normalized->>'organization_code', 'organization_code'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'job-alio:posting', 'JobPosting', r.normalized->>'posting_id', 'posting_id'
    WHERE r.source_id = 'job_alio'
    UNION ALL
    SELECT 'source:posting:nara_job', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'nara_job'
    UNION ALL
    SELECT 'source:posting:jobkorea', 'JobPosting',
           encode(sha256(convert_to(r.normalized->>'posting_id','UTF8')),'hex'), 'posting_id'
    WHERE r.source_id = 'jobkorea'
) ref
WHERE ref.code IS NOT NULL
UNION ALL
SELECT 'hop:'||r.run_id||':'||r.record_id::text,r.run_id,
 'qnet:exam-session:'||encode(sha256(convert_to(r.source_record_id,'UTF8')),'hex'),
 'ExamSession',r.source_record_id,'source_record_id' FROM records r WHERE r.source_id='qnet_schedule'
),
refs AS MATERIALIZED(SELECT q.*,substring(q.record_id from '[^:]+$')::bigint AS numeric_record_id FROM raw_refs q),
 target_assessments AS MATERIALIZED(SELECT u.run_id,
 ingestion.source_graph_run_is_valid(u.run_id) AS valid FROM ready_runs u
 WHERE u.run_id=jobs OR (jobs='ALL_CHECKPOINTED' AND EXISTS(SELECT 1 FROM ingestion.graph_export g WHERE g.run_id=u.run_id))),
 touched AS MATERIALIZED(SELECT DISTINCT q.identity_id FROM refs q
 JOIN target_assessments a USING(run_id) WHERE a.valid),
needed_edge_runs AS MATERIALIZED(SELECT DISTINCT q.run_id FROM refs q JOIN touched t USING(identity_id)),
edge_assessments AS MATERIALIZED(SELECT * FROM target_assessments UNION ALL
 SELECT u.run_id,ingestion.source_graph_run_is_valid(u.run_id) FROM ready_runs u
 JOIN needed_edge_runs n USING(run_id) WHERE NOT EXISTS(SELECT 1 FROM target_assessments a WHERE a.run_id=u.run_id)),

 owners AS MATERIALIZED(
 SELECT DISTINCT ON(q.identity_id,r.source_id) q.identity_id,r.source_id,r.run_id
 FROM refs q JOIN touched t USING(identity_id)
 JOIN edge_assessments a ON a.run_id=q.run_id AND a.valid
 JOIN records r ON q.run_id=r.run_id AND r.record_id=q.numeric_record_id
 WHERE ((r.source_id='job_alio' AND q.kind='JobPosting')
 OR (r.source_id='ncs_competency' AND q.kind='Competency')
 OR (r.source_id='ncs_career_path' AND q.kind='Occupation')
 OR (r.source_id='ncs_qualification' AND q.kind='Competency')
 OR (r.source_id='qnet_schedule' AND q.kind='ExamSession'))
 ORDER BY q.identity_id,r.source_id,r.created_at DESC,r.run_id DESC
 ), pairs AS(
 SELECT o.identity_id AS owner_id,r.source_id,r.run_id,r.source_record_id,
 CASE WHEN r.source_id='qnet_schedule' THEN target.identity_id ELSE o.identity_id END AS from_id,
 CASE WHEN r.source_id='qnet_schedule' THEN o.identity_id ELSE target.identity_id END AS to_id,
 CASE r.source_id WHEN 'job_alio' THEN 'EMPLOYER' WHEN 'ncs_competency' THEN 'CLASSIFIED_AS'
 WHEN 'ncs_career_path' THEN 'HAS_CAREER_COMPETENCY' WHEN 'ncs_qualification' THEN 'QUALIFICATION_MAPPING'
 WHEN 'qnet_schedule' THEN 'HAS_EXAM_SESSION' END AS edge_kind,
 (CASE WHEN r.source_id='jobkorea' THEN ingestion.jobkorea_graph_facts(r.normalized)
 ELSE r.normalized-ARRAY['definition','eligibility_text','disqualification_text','preference_text','selection_text','address','website','source_url'] END)::text AS facts_json
 FROM owners o JOIN refs self ON self.run_id=o.run_id AND self.identity_id=o.identity_id
 JOIN records r ON r.run_id=self.run_id AND r.record_id=self.numeric_record_id
 JOIN refs target ON target.run_id=self.run_id AND target.numeric_record_id=self.numeric_record_id
 AND ((r.source_id='job_alio' AND target.kind='Organization')
 OR (r.source_id='ncs_competency' AND target.kind='Occupation')
 OR (r.source_id='ncs_career_path' AND target.kind='Competency')
 OR (r.source_id='ncs_qualification' AND target.kind='Qualification')
 OR (r.source_id='qnet_schedule' AND target.kind='Qualification'))
 ), dedup AS(
 SELECT DISTINCT ON(owner_id,source_id,from_id,to_id,edge_kind,
 CASE WHEN source_id IN('job_alio','ncs_competency') THEN '' ELSE source_record_id END) * FROM pairs
 ORDER BY owner_id,source_id,from_id,to_id,edge_kind,
 CASE WHEN source_id IN('job_alio','ncs_competency') THEN '' ELSE source_record_id END,source_record_id DESC
 ),
 current_edges AS MATERIALIZED(SELECT from_id,to_id FROM dedup),

 wanted AS MATERIALIZED(SELECT q.identity_id FROM refs q JOIN target_assessments a USING(run_id) WHERE a.valid
 UNION SELECT from_id FROM current_edges
 UNION SELECT to_id FROM current_edges),
 needed_candidate_runs AS MATERIALIZED(SELECT DISTINCT q.run_id FROM refs q JOIN wanted w USING(identity_id)),
candidate_assessments AS MATERIALIZED(SELECT * FROM edge_assessments UNION ALL
 SELECT u.run_id,ingestion.source_graph_run_is_valid(u.run_id) FROM ready_runs u
 JOIN needed_candidate_runs n USING(run_id) WHERE NOT EXISTS(SELECT 1 FROM edge_assessments a WHERE a.run_id=u.run_id)),
candidate_rows AS MATERIALIZED(SELECT q.record_id,q.run_id,q.identity_id,q.kind,q.code,q.field,r.source_id,r.source_record_id,
 r.record_id AS numeric_record_id,r.normalized,
 NULL::text AS facts_json,u.created_at,
 CASE q.kind
 WHEN 'Organization' THEN CASE WHEN r.source_id='alio_organization' THEN r.normalized->>'name' ELSE r.normalized->>'organization_name' END
 WHEN 'JobPosting' THEN r.normalized->>'title'
 WHEN 'Occupation' THEN r.normalized->>'occupation_name'
 WHEN 'Competency' THEN CASE WHEN r.source_id='ncs_competency' THEN r.normalized->>'name' ELSE r.normalized->>'competency_name' END
 WHEN 'Qualification' THEN r.normalized->>'qualification_name'
 WHEN 'ExamSession' THEN r.normalized->>'name' END AS proposed_name,
 CASE WHEN (q.kind='Organization' AND r.source_id='alio_organization')
 OR (q.kind='Competency' AND r.source_id='ncs_competency')
 OR (q.kind='Qualification' AND r.source_id='ncs_qualification') THEN 0 ELSE 1 END AS owner_priority,
 CASE WHEN r.source_id IN('alio_organization','ncs_competency','ncs_qualification') THEN 0 ELSE 1 END AS name_priority
FROM refs q JOIN records r ON r.run_id=q.run_id AND r.record_id=q.numeric_record_id
JOIN ready_runs u ON u.run_id=r.run_id
JOIN candidate_assessments a ON a.run_id=r.run_id AND a.valid),
candidates AS MATERIALIZED(SELECT c.* FROM candidate_rows c JOIN wanted w USING(identity_id)),
 facts AS MATERIALIZED(SELECT c.*,row_number() OVER(PARTITION BY c.identity_id ORDER BY owner_priority,
 created_at DESC,c.run_id DESC,CASE WHEN normalized->>'representation'='detail' THEN 0 ELSE 1 END,
 numeric_record_id DESC,c.record_id DESC) AS choice FROM candidates c),
 names AS(SELECT c.*,row_number() OVER(PARTITION BY c.identity_id ORDER BY
 (nullif(btrim(proposed_name),'') IS NULL),name_priority,created_at DESC,c.run_id DESC,
 CASE WHEN normalized->>'representation'='detail' THEN 0 ELSE 1 END,
 numeric_record_id DESC,c.record_id DESC) AS choice FROM candidates c),
 current_facts AS MATERIALIZED(SELECT * FROM facts WHERE choice=1),
 posting_records AS MATERIALIZED(SELECT r.run_id,r.source_id,r.normalized,
 r.normalized->>'posting_id' AS posting_id,r.normalized->>'representation' AS representation
 FROM records r JOIN current_facts f ON f.run_id=r.run_id AND f.source_id=r.source_id
 AND f.normalized->>'posting_id'=r.normalized->>'posting_id'
 WHERE f.kind='JobPosting' AND f.source_id IN('job_alio','nara_job')),
 posting_sets AS MATERIALIZED(SELECT p.run_id,p.source_id,p.posting_id,
 jsonb_object_agg(p.representation,p.normalized) AS forms FROM posting_records p
 GROUP BY p.run_id,p.source_id,p.posting_id),
 job_facts AS MATERIALIZED(SELECT p.run_id,p.posting_id,
 ((p.forms->'list')||jsonb_strip_nulls(p.forms->'detail'))-'representation' AS normalized
 FROM posting_sets p WHERE p.source_id='job_alio' AND p.forms ?& ARRAY['list','detail']),
 nara_facts AS MATERIALIZED(SELECT p.run_id,p.posting_id,
 ((p.forms->'list')||jsonb_strip_nulls(p.forms->'detail')||jsonb_strip_nulls(p.forms->'positions')||jsonb_strip_nulls(p.forms->'files'))-'representation' AS normalized
 FROM posting_sets p WHERE p.source_id='nara_job' AND p.forms ?& ARRAY['list','detail','positions','files']
 AND coalesce((p.forms->'list'->>'ongoing')::boolean,false))
 SELECT f.identity_id,f.kind,f.code,coalesce(nullif(btrim(n.proposed_name),''),f.kind||' '||f.code),
 CASE WHEN f.kind='JobPosting' THEN coalesce(nullif(btrim(n.proposed_name),''),f.kind||' '||f.code) END,
 n.run_id,n.record_id,f.source_id,f.run_id,f.source_record_id,
 to_char(f.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 selected.facts_json,encode(sha256(convert_to(selected.facts_json,'UTF8')),'hex')
 FROM current_facts f JOIN names n USING(identity_id)
 LEFT JOIN job_facts j ON j.run_id=f.run_id AND j.posting_id=f.normalized->>'posting_id'
 LEFT JOIN nara_facts k ON k.run_id=f.run_id AND k.posting_id=f.normalized->>'posting_id'
 CROSS JOIN LATERAL(SELECT ingestion.source_graph_entity_facts(f.kind,f.source_id,
 CASE WHEN f.kind='JobPosting' AND f.source_id='job_alio' THEN
  coalesce(j.normalized,f.normalized)
 WHEN f.kind='JobPosting' AND f.source_id='nara_job' THEN
  coalesce(k.normalized,f.normalized)
 ELSE f.normalized END)::text AS facts_json) selected
 WHERE n.choice=1 ORDER BY f.identity_id;
END $$;

COMMIT;
